def sum_recursive(n):
    if n == 0:
        return 0
    return n + sum_recursive(n - 1)

# Test
print(sum_recursive(5))  # Output: 15

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

# Test
print(factorial(4))  # Output: 24

def fibonacci(n):
    if n == 0:
        return 0
    elif n == 1:
        return 1
    return fibonacci(n - 1) + fibonacci(n - 2)

# Test
print(fibonacci(6))  # Output: 8

def power(a, b):
    if b == 0:
        return 1
    return a * power(a, b - 1)

# Test
print(power(2, 3))  # Output: 8

def reverse_string(s):
    if len(s) == 0:
        return ""
    return s[-1] + reverse_string(s[:-1])

# Test
print(reverse_string("hello"))  # Output: "olleh"

def is_palindrome(s):
    if len(s) <= 1:
        return True
    if s[0] != s[-1]:
        return False
    return is_palindrome(s[1:-1])

# Test
print(is_palindrome("madam"))  # Output: True

def count_digits(n):
    if n < 10:
        return 1
    return 1 + count_digits(n // 10)

# Test
print(count_digits(12345))  # Output: 5

def gcd(a, b):
    if b == 0:
        return a
    return gcd(b, a % b)

# Test
print(gcd(48, 18))  # Output: 6

def decimal_to_binary(n):
    if n == 0:
        return "0"
    elif n == 1:
        return "1"
    return decimal_to_binary(n // 2) + str(n % 2)

# Test
print(decimal_to_binary(10))  # Output: "1010"

def sum_of_digits(n):
    if n < 10:
        return n
    return n % 10 + sum_of_digits(n // 10)

# Test
print(sum_of_digits(123))  # Output: 6

def sum_list(lst):
    if not lst:
        return 0
    return lst[0] + sum_list(lst[1:])

# Test
print(sum_list([1, 2, 3, 4, 5]))  # Output: 15

def collatz_steps(n):
    if n == 1:
        return 0
    elif n % 2 == 0:
        return 1 + collatz_steps(n // 2)
    else:
        return 1 + collatz_steps(3 * n + 1)

# Test
print(collatz_steps(3))  # Output: 7

def is_sorted(lst):
    if len(lst) < 2:
        return True
    if lst[0] > lst[1]:
        return False
    return is_sorted(lst[1:])

# Test
print(is_sorted([1, 2, 3, 4, 5]))  # Output: True

def find_max(lst):
    if len(lst) == 0:
        return None
    if len(lst) == 1:
        return lst[0]
    max_rest = find_max(lst[1:])
    return max(lst[0], max_rest)

# Test
print(find_max([3, 1, 4, 1, 5, 9, 2]))  # Output: 9

def count_zeros(n):
    if n < 10:
        return 1 if n == 0 else 0
    last_digit = n % 10
    if last_digit == 0:
        return 1 + count_zeros(n // 10)
    else:
        return count_zeros(n // 10)

# Test
print(count_zeros(10203))  # Output: 2

def flatten_list(nested_list):
    result = []
    for element in nested_list:
        if isinstance(element, list):
            result.extend(flatten_list(element))
        else:
            result.append(element)
    return result

# Test
print(flatten_list([1, [2, 3], [4, [5, 6]], 7]))  # Output: [1, 2, 3, 4, 5, 6, 7]
